private def divisorTau (n : ℕ) : ℝ := (n.divisors.card : ℝ)

private def conductorWindows (R Q : ℕ) : Finset ℕ :=
  (Finset.range (Nat.log2 Q + 1)).filter (fun j ↦ R * 2 ^ j < Q)
